"""把某一周的笔记片段包成可单独打开的预览页（样式仿照网站，未接入网站）。"""
import sys
HEAD = '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>样稿 · 商业数学 T2 W5 概率基础</title>\n<style>\n:root{--ink:#1c2a3a;--navy:#173860;--muted:#5b6b80;--line:#dfe9f5}\nbody{margin:0;background:#f4f7fb;color:var(--ink);font:16px/1.75 -apple-system,"PingFang SC","Microsoft YaHei",system-ui,sans-serif}\n.wrap{max-width:860px;margin:0 auto;padding:20px 16px 80px}\n.banner{background:#173860;color:#fff;border-radius:12px;padding:16px 18px;margin-bottom:18px}\n.banner b{color:#f6e3b4}\n.gx{background:#fff;border:1px solid var(--line);border-radius:12px;padding:8px 20px 24px}\nh4.kp-h{font-size:19px;color:var(--navy);margin:30px 0 6px;padding:8px 12px;background:#eaf3fc;border-radius:8px}\n.kp-src{font-size:12px;color:var(--muted);margin:0 0 10px}\n.callout{padding:10px 14px;margin:12px 0;border-radius:0 8px 8px 0}\n.callout.blue{border-left:3px solid #16569c;background:#f3f8ff}\n.callout.red{border-left:3px solid #b03030;background:#fff7f7;color:#3a2a2a}\n.c-blue{color:#1f5f9e;font-weight:600;margin:18px 0 6px}\n.formula{background:#fbf7ec;border:1px solid #efe2bf;border-radius:8px;padding:10px 14px;margin:10px 0;text-align:center;font-size:17px}\n.frac{display:inline-flex;flex-direction:column;vertical-align:middle;text-align:center;margin:0 2px;line-height:1.25}\n.frac .n{border-bottom:1.5px solid currentColor;padding:0 3px}.frac .d{padding:0 3px}\ndetails{margin:6px 0 14px;border:1px solid var(--line);border-radius:8px;padding:6px 12px;background:#fcfdff}\nsummary{cursor:pointer;color:#16569c;font-weight:600;min-height:32px;line-height:32px}\n.diagram{text-align:center;margin:12px 0}.diagram svg{max-width:100%;height:auto}.cap{font-size:13px;color:var(--muted)}\ntable.kp-tbl{border-collapse:collapse;width:100%;font-size:15px}.kp-tbl th,.kp-tbl td{border:1px solid var(--line);padding:6px 8px;text-align:left}.kp-tbl th{background:#eaf3fc}\n</style></head><body><div class="wrap">\n'
def main(frag, out, title):
    body = open(frag, encoding="utf-8").read()
    page = HEAD.replace("<title>样稿 · 商业数学 T2 W5 概率基础</title>", f"<title>{title}</title>")
    page += f'<div class="banner"><b>预览</b> · {title}<br>结构：概念 → 图 → 课件例题（先做，再点「看解答」）→ 易错 → 常见疑惑。本页样式仿照网站，未接入网站。</div><article class="gx">'
    page += body + "</article></div></body></html>"
    open(out, "w", encoding="utf-8").write(page)
if __name__ == "__main__":
    main(*sys.argv[1:4])
